    H=len(g);W=len(g[0]);seen=set(); res=[]
    for i in range(H):
        for j in range(W):
            if (i,j) in seen: continue
            c=g[i][j]; st=[(i,j)];seen.add((i,j));cells=[]
            while st:
                a,b=st.pop();cells.append((a,b))
                for di,dj in D4:
                    x,y=a+di,b+dj
                    if 0<=x<H and 0<=y<W and (x,y) not in seen and g[x][y]==c:
                        seen.add((x,y));st.append((x,y))
            res.append((c,tuple(sorted(cells))))
    return res
def f_bboxobj(g):
    H=len(g);W=len(g[0])
    cnt=Counter(v for r in g for v in r); bg=cnt.most_common(1)[0][0]
    cs=comps(g)
    boxes=[(c,(min(p[0] for p in cl),max(p[0] for p in cl),min(p[1] for p in cl),max(p[1] for p in cl))) for c,cl in cs if len(cl)>1]
    singles=[(c,cl[0]) for c,cl in cs if len(cl)==1]
    ret=[r[:] for r in g]
    for c,(xi,yi) in singles:
        candlist=[b[0] for b in boxes if b[1][0]<=xi<=b[1][1] and b[1][2]<=yi<=b[1][3]]
        nonbg=[v for v in candlist if v!=bg]
        ret[xi][yi]=nonbg[0] if nonbg else bg
    return ret
for p in ['Demo pair 1','Demo pair 2','Demo pair 3']:
    print(p, f_bboxobj(G[p+' input'])==G[p+' output'])
